/**
 * Identifies the chat a one-time payment was made for, so the purchase
 * unlocks that chat and not the next file the user drops in.
 *
 * Re-uploading the same export has to produce the same value, so it is derived
 * from the messages themselves — never from the file name or the upload time.
 */
export const chatFingerprint = (chat: any): string | null => {
  const messages = chat?.chatObject;
  if (!messages?.length) return null;

  const first = messages[0];
  const last = messages[messages.length - 1];
  const authors = [...new Set(messages.map((m: any) => m.author))]
    .sort()
    .join("|");

  const seed = [
    messages.length,
    new Date(first.date).getTime(),
    new Date(last.date).getTime(),
    first.message,
    last.message,
    authors,
  ].join("�");

  // djb2: short and stable, and cheap enough to run on every render.
  let hash = 5381;
  for (let i = 0; i < seed.length; i++) {
    hash = (hash * 33) ^ seed.charCodeAt(i);
  }
  return (hash >>> 0).toString(36);
};
